mapper.update:
UPDATE iam_file_object
SET reference_count = reference_count + 1, updated_at = #{now}
WHERE id = #{objectId}

UPDATE iam_file_object
SET reference_count = CASE WHEN reference_count > 0 THEN reference_count - 1 ELSE 0 END,
    updated_at = #{now}
WHERE id = #{objectId}

UPDATE iam_file
SET status = 'PURGING', version = version + 1, updated_at = #{now}
WHERE tenant_id = #{tenantId} AND id = #{fileId}
  AND version = #{expectedVersion} AND status = 'DELETED'

UPDATE iam_file_object
SET status = 'PURGING', updated_at = #{now}
WHERE id = #{objectId} AND status IN ('ACTIVE','QUARANTINED')

UPDATE iam_file
SET status = 'PURGED', version = version + 1, updated_at = #{now}
WHERE tenant_id = #{tenantId} AND id = #{fileId} AND status = 'PURGING'

UPDATE iam_file_object
SET status = 'PURGED', updated_at = #{now}
WHERE id = #{objectId} AND status = 'PURGING'

UPDATE iam_file
SET status = 'DELETED', version = version + 1, updated_at = #{now}
WHERE tenant_id = #{tenantId} AND id = #{fileId} AND status = 'PURGING'

UPDATE iam_file_object
SET status = 'ACTIVE', updated_at = #{now}
WHERE id = #{objectId} AND status = 'PURGING'

UPDATE iam_file
SET status = 'DELETED', delete_marker = #{deleteMarker}, version = version + 1, updated_at = #{now}
WHERE tenant_id = #{tenantId} AND id = #{fileId} AND version = #{expectedVersion}

UPDATE iam_file
SET status = 'SCANNING', scan_status = 'SCANNING', version = version + 1, updated_at = #{now}
WHERE id = #{fileId} AND status = 'VERIFYING' AND scan_status = 'PENDING'

UPDATE iam_file
SET scan_status = 'SCANNING', version = version + 1, updated_at = #{now}
WHERE id = #{fileId} AND tenant_id = #{tenantId}
  AND status = 'SCANNING' AND scan_status = 'FAILED'

UPDATE iam_file_scan_record
SET result = #{result}, threat_code = #{threatCode}, error_code = #{errorCode},
    signature_version = #{signatureVersion}, completed_at = #{completedAt}
WHERE tenant_id = #{tenantId} AND file_id = #{fileId}
  AND scan_attempt = #{attempt} AND result = 'SCANNING'

UPDATE iam_file
SET scan_status = 'FAILED', updated_at = #{now}
WHERE tenant_id = #{tenantId} AND id = #{fileId} AND scan_status = 'SCANNING'

UPDATE iam_file
SET status = #{status}, scan_status = #{scanStatus}, version = version + 1, updated_at = #{now}
WHERE tenant_id = #{tenantId} AND id = #{fileId} AND version = #{expectedVersion}

mapper.select:
SELECT id, tenant_id, upload_session_id, part_number, part_size,
    LOWER(HEX(part_sha256)) AS partSha256Hex, storage_etag, status, uploaded_at, version
FROM iam_file_upload_part
WHERE tenant_id = #{tenantId} AND upload_session_id = #{uploadSessionId}
  AND part_number = #{partNumber}

mapper.update:
UPDATE iam_file_upload_session
SET status = #{status}, completed_file_id = #{completedFileId}, version = version + 1,
    updated_at = #{now}
WHERE tenant_id = #{tenantId} AND id = #{uploadId} AND version = #{expectedVersion}

UPDATE iam_file_upload_session
SET uploaded_part_count = uploaded_part_count + 1,
    status = CASE WHEN status = 'INIT' THEN 'UPLOADING' ELSE status END,
    version = version + 1, updated_at = #{now}
WHERE tenant_id = #{tenantId} AND id = #{uploadId}

UPDATE iam_file_upload_session
SET status = 'ABORTED', version = version + 1, updated_at = #{now}
WHERE tenant_id = #{tenantId} AND id = #{uploadId} AND version = #{expectedVersion}

UPDATE iam_file_tenant_quota
SET used_logical_bytes = #{usedLogicalBytes}, reserved_bytes = #{reservedBytes},
    version = version + 1, updated_at = #{now}
WHERE tenant_id = #{tenantId} AND version = #{expectedVersion}
  AND (#{usedLogicalBytes} + #{reservedBytes}) <= quota_bytes

mapper.select:
SELECT tenant_id, id AS sessionId, quota_reservation_bytes, version
FROM iam_file_upload_session
WHERE status IN ('INIT','UPLOADING','VERIFYING','MERGING') AND expire_at < #{now}
ORDER BY expire_at, id
LIMIT #{limit}

mapper.update:
UPDATE iam_file_upload_session
SET status = 'EXPIRED', version = version + 1, updated_at = #{now}
WHERE tenant_id = #{tenantId} AND id = #{sessionId} AND version = #{expectedVersion}
  AND status IN ('INIT','UPLOADING','VERIFYING','MERGING')

UPDATE iam_file_tenant_quota
SET reserved_bytes = CASE WHEN reserved_bytes >= #{bytes} THEN reserved_bytes - #{bytes} ELSE 0 END,
    version = version + 1, updated_at = #{now}
WHERE tenant_id = #{tenantId}

UPDATE iam_file
SET dlp_status = #{dlpStatus}, status = #{status}, version = version + 1, updated_at = #{now}
WHERE tenant_id = #{tenantId} AND id = #{fileId}

UPDATE iam_file
SET storage_tier = #{storageTier}, status = #{status}, version = version + 1, updated_at = #{now}
WHERE tenant_id = #{tenantId} AND id = #{fileId}
